128	    params.candidate_ids = std::move(bf_keys.value());
129	  }
130	  // Push down remaining filters (delete / forward) so filtered docs are
131	  // skipped during scoring and we still return up to topk results.
132	  params.filter = doc_filter_->empty() ? nullptr : doc_filter_;
