135	      segment_->fts_search(fts_cond->field_name, *fts_cond->fts_ast, params);
136	  if (!results) {
137	    return tl::make_unexpected(results.error());
138	  }
139	
140	  return std::make_shared<FtsIndexResults>(std::move(results.value()));
141	}
